"""Syntax tree for a parsed query. Shared contract between parser and engine.

All nodes are plain dataclasses. Names (columns, aliases, tables) are stored
exactly as written, with quotes removed and ``""`` unescaped; matching them
case-insensitively is the engine's job. Function names are stored uppercased.
"""

from dataclasses import dataclass, field
from typing import List, Optional, Union


@dataclass
class Literal:
    value: Union[int, float, str, bool, None]  # NULL is None


@dataclass
class Column:
    name: str


@dataclass
class Unary:
    op: str  # "-" or "NOT"
    operand: "Expr"


@dataclass
class Binary:
    # One of: OR AND = != < <= > >= + - || * /   ("<>" is normalized to "!=")
    op: str
    left: "Expr"
    right: "Expr"


@dataclass
class IsNull:
    operand: "Expr"
    negated: bool  # True for IS NOT NULL


@dataclass
class In:
    operand: "Expr"
    items: List["Expr"]
    negated: bool


@dataclass
class Between:
    operand: "Expr"
    low: "Expr"
    high: "Expr"
    negated: bool


@dataclass
class Like:
    operand: "Expr"
    pattern: "Expr"
    negated: bool


@dataclass
class Call:
    name: str  # uppercased, e.g. "COUNT"
    args: List["Expr"]
    star: bool = False  # True only for COUNT(*), with args == []


Expr = Union[Literal, Column, Unary, Binary, IsNull, In, Between, Like, Call]


@dataclass
class SelectItem:
    expr: Expr
    alias: Optional[str]
    text: str  # source text of expr exactly as written, e.g. "price * 2"


@dataclass
class OrderItem:
    expr: Expr
    descending: bool


@dataclass
class Query:
    distinct: bool
    columns: Optional[List[SelectItem]]  # None means SELECT *
    table: str
    where: Optional[Expr] = None
    group_by: List[Expr] = field(default_factory=list)
    having: Optional[Expr] = None
    order_by: List[OrderItem] = field(default_factory=list)
    limit: Optional[int] = None
    offset: Optional[int] = None
EOF
