python3 -m unittest discover -s tests -t . 2>&1 | tail -4; python3 -c "
import minisql
for q in ['SELECT category, COUNT(*) FROM products WHERE FALSE GROUP BY category',
          'SELECT COUNT(*) FROM products WHERE FALSE',
          'SELECT ROUND(2.5), ROUND(-2.5), ROUND(1.005, 2), 7/2, 1+2.0 FROM products LIMIT 1',
          'SELECT DISTINCT category FROM products ORDER BY 1 DESC',
          'SELECT \"name\" || \'!\' AS x FROM products ORDER BY x LIMIT 2 OFFSET 1',
          'SELECT price FROM products ORDER BY name']:
    r = minisql.run(q, 'data'); print(r.columns, r.rows)
for q in ['SELECT name, COUNT(*) FROM products', 'SELECT 1 + \'a\' FROM products', 'SELECT FROM products', 'SELECT SUM(COUNT(*)) FROM products']:
    try: minisql.run(q, 'data')
    except minisql.QueryError as e: print('QueryError:', e)
"; wc -l minisql/*.py tests/*.py

